(() => {
 const L=window.NEMO_LANDING,state=window.NEMO_LANDING_STATE,config=state?.config||L.defaults;
 const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
 function visual(p){let key=p.visual;if(key?.startsWith('/media/')||key==='photo'){const image=el('img');image.src=key==='photo'?'assets/hero.png':key;image.alt=p.title;image.loading='lazy';return image;}const art=el('div',undefined,'atlas '+({home:'a-home',cafe:'a-cafe',estimate:'a-estimate',measure:'a-measure',material:'a-material',complete:'a-complete',office:'office-art',popup:'popup-art'}[key]||key||''));art.setAttribute('role','img');art.setAttribute('aria-label',p.title);return art;}
 function renderProjects(category){const strip=document.querySelector('.portfolio-strip');strip.replaceChildren();const pool=state?.projects||[];for(const p of L.pickProjects(pool,category,6)){const card=el('button',undefined,'project-card');card.type='button';card.dataset.project=p.id;card.dataset.category=p.category;const image=el('div',undefined,'project-image');image.appendChild(visual(p));const caption=el('div',undefined,'project-caption');caption.append(el('span',p.title),el('span','↗'));card.append(image,caption,el('small',[...new Set([p.category,p.showMeta===false?'':p.style,p.kind].filter(Boolean))].join(' · ')));strip.appendChild(card);}const all=el('a',undefined,'project-card project-all');all.href='portfolios.html'+(category==='전체'?'':'?space='+encodeURIComponent(category));all.dataset.category=category;const box=el('div',undefined,'project-image');box.append(el('span','더 많은 공간을 만나보세요.'),el('strong',category==='전체'?'포트폴리오 전체 보기':category+' 공간 전체 보기'),el('span','↗'));all.append(box,el('span','포트폴리오에서 더 살펴보기 ↗','project-all-caption'));strip.appendChild(all);}
 document.querySelector('.reviews-heading .eyebrow').textContent=config.reviewEyebrow;document.querySelector('#reviews-title').textContent=config.reviewTitle;
 const meta=document.querySelector('.review-map-meta p');meta.replaceChildren(document.createTextNode(config.totalLabel+' - '),el('strong',config.totalProjects),document.createTextNode(' '),el('span','('+config.overseasLabel+' '+config.overseasProjects+')'));document.querySelector('.review-data-source').textContent=config.dataSource;
 const track=document.querySelector('.review-track');track.replaceChildren(...config.marquee.map(r=>{const q=el('blockquote','“'+r.text+'”');q.appendChild(el('small',r.label));return q;}));document.querySelector('.review-board').hidden=config.marquee.length===0;
 const overseas=document.querySelector('.overseas-project-list');overseas.replaceChildren(...config.overseas.map(r=>{const li=el('li'),h=el('h4',r.country+' · '+r.title);li.appendChild(h);if(r.description)li.appendChild(el('p',r.description));return li;}));if(!config.overseas.length)overseas.appendChild(el('li','등록된 해외 프로젝트가 없습니다.'));
 const groups=L.groupReviews(config.domestic),map=document.querySelector('.review-map-canvas'),popup=document.querySelector('#map-review-popup');map.querySelectorAll('.review-pin').forEach(n=>n.remove());popup.setAttribute('role','region');popup.setAttribute('aria-label','지역 후기');popup.setAttribute('aria-live','polite');let selected=null,index=0;
 function hideReview(){selected=null;popup.hidden=true;map.querySelectorAll('.review-pin').forEach(n=>{n.classList.remove('selected');n.setAttribute('aria-expanded','false');});}
 function showReview(group,pin,i=0){selected=group;index=(i+group.reviews.length)%group.reviews.length;const r=group.reviews[index];popup.replaceChildren(el('span',[group.label,r.kind].filter(Boolean).join(' · '),'map-review-region'),el('strong',r.person,'map-review-person'),el('p','“'+r.quote+'”','map-review-quote'));if(group.reviews.length>1){const controls=el('div',undefined,'map-review-controls'),prev=el('button','←'),next=el('button','→');prev.type=next.type='button';prev.setAttribute('aria-label','같은 지역 이전 후기');next.setAttribute('aria-label','같은 지역 다음 후기');prev.onclick=()=>showReview(group,pin,index-1);next.onclick=()=>showReview(group,pin,index+1);controls.append(prev,el('span',(index+1)+' / '+group.reviews.length),next);popup.appendChild(controls);}popup.hidden=false;map.querySelectorAll('.review-pin').forEach(n=>{n.classList.toggle('selected',n===pin);n.setAttribute('aria-expanded',String(n===pin));});}
 for(const group of groups){const pin=el('button',undefined,'review-pin');pin.type='button';pin.style.left=group.x+'%';pin.style.top=group.y+'%';pin.setAttribute('aria-label',group.label+' 후기 '+group.reviews.length+'개 보기');pin.setAttribute('aria-controls','map-review-popup');pin.setAttribute('aria-expanded','false');pin.append(el('span',undefined,'pin-dot'),el('span',group.label,'pin-label'));if(group.reviews.length>1)pin.appendChild(el('span',String(group.reviews.length),'pin-count'));pin.addEventListener('click',()=>selected===group?hideReview():showReview(group,pin));map.appendChild(pin);}
 document.addEventListener('pointerdown',e=>{if(!e.target.closest('.review-pin,.map-review-popup'))hideReview();});document.addEventListener('keydown',e=>{if(e.key==='Escape')hideReview();});
 window.NEMO_LANDING_VIEW={renderProjects,hideReview};
})();
